  /// Stored for historical reference (product may be updated or deleted
  /// later).
  shopping_mall_product_id String @db.Uuid

  /// Specific product variant (SKU) purchased. Reference to {@link
  /// shopping_mall_product_variants.id}. Captures exact variant at time of
  /// order.
  shopping_mall_product_variant_id String @db.Uuid

  /// Seller fulfilling this line item. Reference to {@link
  /// shopping_mall_sellers.id}. Multi-seller orders have multiple line items
  /// with different sellers.
  shopping_mall_seller_id String @db.Uuid

  /// Stock Keeping Unit identifier for this specific product variant. Snapshot
  /// of SKU at order time.
  sku String

  /// Product name snapshot at time of order (product may be renamed or deleted
  /// later). Used for customer-facing receipts and order history.
  product_name String

  /// JSON snapshot of variant attributes (color, size, options, etc.) at time
  /// of order. Enables customers to remember exact variant purchased.
  variant_details String?

  /// Price per unit at time of order in order's currency. Locked in at order
  /// creation, not affected by later price changes. Stored in cents precision.
  unit_price Float @db.DoublePrecision

  /// Number of units ordered for this line item. Must be positive integer.
  quantity Int @db.Integer

  /// Line item subtotal = unit_price × quantity before line-item-specific
  /// discounts. Stored in cents precision.
  line_subtotal Float @db.DoublePrecision

  /// Discount applied to this specific line item (if any). Stored in cents
  /// precision. Used for items with quantity-based discounts.
  line_discount Float @db.DoublePrecision

  /// Line item total = line_subtotal - line_discount. This is the amount for
  /// this item in the order. Stored in cents precision.
  line_total Float @db.DoublePrecision

  /// Fulfillment status of this specific line item: pending, confirmed,
  /// picked, packed, shipped, in_transit, out_for_delivery, delivered,
  /// cancelled, returned. Enables tracking individual items in multi-seller
  /// orders.
  item_status String

  /// Timestamp when line item was added to order. Normally same as
  /// order.created_at but may differ if order items are added asynchronously.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last line item update (status change, etc.). Enables
  /// tracking item-level changes.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)
  product shopping_mall_products @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  productVariant shopping_mall_product_variants @relation(fields: [shopping_mall_product_variant_id], references: [id], onDelete: Cascade, map: "shopping_mall_order_line_items_shopping_mall_product_v_d3362cc7")
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)

  shopping_mall_return_requests shopping_mall_return_requests[]

  @@index([shopping_mall_product_id])

  @@index([shopping_mall_order_id])
  @@index([shopping_mall_seller_id])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_product_variant_id], map: "shopping_mall_order_line_items_shopping_mall_product_v_ae2928bf")
  @@index([item_status])
}

/// Immutable append-only audit trail of all order status transitions.
/// Captures point-in-time snapshots of status changes with exact timestamp
/// and triggering actor. Enables complete visibility into order lifecycle
/// for customers, sellers, and admins. Each status change creates a new
/// record (never updated or deleted). Used for compliance auditing, dispute
/// resolution, and performance analytics.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_order_status_history {
  //----
  // COLUMNS
  //----
  /// Primary Key
  id String @id @db.Uuid

  /// Order for which status changed. Reference to {@link
  /// shopping_mall_orders.id}
  shopping_mall_order_id String @db.Uuid

  /// Order status before this transition. Null if this is the initial status
  /// at order creation.
  previous_status String?

  /// Order status after this transition. The current status of the order at
  /// this point in time.
  new_status String

  /// Reason or context for status change (e.g., 'payment authorized', 'seller
  /// confirmed', 'carrier pickup', 'delivered by carrier'). Helps understand
  /// why transition occurred.
  status_transition_reason String?

  /// Actor who triggered the status change: 'customer', 'seller', 'admin',
  /// 'system', 'payment_processor', 'carrier'. Identifies source of the
  /// transition.
  triggered_by String

  /// ID of actor who triggered change (customer_id, seller_id, admin_id, or
  /// 'system'). Enables audit trail of specific users.
  triggered_by_id String?

  /// Number of seconds order spent in previous status before transitioning.
  /// Null if first status. Used for SLA tracking and performance analytics.
  duration_in_previous_status Int? @db.Integer

  /// Timestamp when status transition occurred. ISO 8601 format with timezone.
  /// Immutable after creation - defines exact moment of transition.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)

  // spellchecker: ignore-next-line
  @@index([shopping_mall_order_id, created_at], map: "shopping_mall_order_status_history_shopping_mall_order_e30a1d11")
  @@index([new_status, created_at])
}

/// Junction table linking orders to shipments. Enables mapping between
/// orders and their corresponding shipment records. Supports multi-shipment
/// orders (order split across multiple packages) and multi-order shipments
/// (consolidation). Maintains relationship between order fulfillment and
/// shipping infrastructure.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_order_shipment_mappings {
  //----
  // COLUMNS
  //----
  /// Primary Key
  id String @id @db.Uuid

  /// Order being shipped. Reference to {@link shopping_mall_orders.id}
  shopping_mall_order_id String @db.Uuid

  /// Shipment record for this order. Reference to {@link
  /// shopping_mall_shipments.id}. One order may have multiple shipments.
  shopping_mall_shipment_id String @db.Uuid

  /// Sequence number if order has multiple shipments. First shipment = 1,
  /// second = 2, etc. Enables ordering of multiple packages.
  mapping_sequence Int @db.Integer

  /// Timestamp when mapping was created (when shipment was assigned to order).
  /// Records when relationship was established.
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade, map: "shopping_mall_order_shipment_mappings_shopping_mall_or_938380e4")
  // spellchecker: ignore-next-line
  shipment shopping_mall_shipments @relation(fields: [shopping_mall_shipment_id], references: [id], onDelete: Cascade, map: "shopping_mall_order_shipment_mappings_shopping_mall_sh_b737c540")

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_order_id, shopping_mall_shipment_id], map: "shopping_mall_order_shipment_mappings_shopping_mall_or_562a788f")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_order_id], map: "shopping_mall_order_shipment_mappings_shopping_mall_or_8478f135")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_shipment_id], map: "shopping_mall_order_shipment_mappings_shopping_mall_sh_aeca0a2e")
}

/// Order-specific tracking information and details. Maintains current
/// tracking state for orders including tracking number, carrier, estimated
/// delivery, and tracking status. Enables customers to monitor order
/// progress through fulfillment and delivery. Links orders to carrier
/// tracking systems.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_order_tracking {
  //----
  // COLUMNS
  //----
  /// Primary Key
  id String @id @db.Uuid

  /// Order being tracked. Reference to {@link shopping_mall_orders.id}
  shopping_mall_order_id String @db.Uuid

  /// Carrier-provided tracking number for this shipment. May be multiple
  /// numbers if order split across packages (stored as comma-separated list).
  tracking_number String?

  /// Shipping carrier name (e.g., 'FedEx', 'UPS', 'DHL', 'USPS'). Enables
  /// linking to carrier tracking systems.
  carrier_name String?

  /// Carrier service type (e.g., 'Ground', 'Express', 'Priority'). Indicates
  /// service level selected.
  carrier_service String?

  /// Latest tracking status from carrier: 'pending_pickup', 'picked_up',
  /// 'in_transit', 'out_for_delivery', 'delivered', 'failed_delivery',
  /// 'returned'. Current state of shipment.
  current_tracking_status String?

  /// Timestamp of most recent carrier tracking update. Enables detection of
  /// stale tracking data.
  last_tracking_update DateTime? @db.Timestamptz

  /// Current location of shipment if provided by carrier (city, country, or
  /// facility name). JSON format if detailed coordinates available.
  current_location String?

  /// Current carrier estimate for delivery (may differ from order's original
  /// estimate). Updated as carrier provides new information.
  estimated_delivery DateTime? @db.Timestamptz

  /// Timestamp when delivery was confirmed by carrier or customer signature.
  /// Marks completion of shipping phase.
  delivery_confirmed_at DateTime? @db.Timestamptz

  /// If delivery failed, reason provided by carrier (address invalid,
  /// recipient unavailable, refused, weather delay, etc.).
  delivery_exception_reason String?

  /// Timestamp when tracking record was created (when shipment was assigned).
  /// Marks start of tracking.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last tracking update. Updated whenever carrier provides new
  /// tracking information.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)

  @@unique([shopping_mall_order_id])

  @@index([current_tracking_status])
  @@index([estimated_delivery])
  @@index([tracking_number(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Customer-specific preferences and settings for their orders. Captures
/// customer's default choices and order-related preferences (shipping method
/// preference, notification settings, etc.). Enables personalization of
/// order experience. Subsidiary table managed through customer account
/// settings.
///
/// @namespace Orders
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_customer_order_preferences {
  //----
  // COLUMNS
  //----
  /// Primary Key
  id String @id @db.Uuid

  /// Customer whose preferences are stored. Reference to {@link
  /// shopping_mall_customers.id}. One-to-one relationship per customer.
  shopping_mall_customer_id String @db.Uuid

  /// Customer's preferred shipping method (standard, express, overnight,
  /// etc.). Pre-selected in checkout for convenience.
  preferred_shipping_method String?

  /// Customer's preferred payment method ID (reference to payment method in
  /// payment system). Pre-selected in checkout.
  preferred_payment_method_id String?

  /// Whether customer prefers to use billing address same as shipping address.
  /// Simplifies checkout.
  use_billing_address Boolean

  /// Whether customer wants order status notifications (email, SMS, push).
  /// Controls notification delivery.
  order_notifications_enabled Boolean

  /// Whether customer opted into promotional newsletter. Used for marketing
  /// communications.
  newsletter_opted_in Boolean

  /// Gift preferences JSON (gift wrap preference, gift message, delivery
  /// timing, etc.). Enables gift order personalization.
  gift_preferences String?

  /// Timestamp when preferences were first created. Marks when customer set up
  /// preferences.
  created_at DateTime @db.Timestamptz

  /// Timestamp of last preference update. Tracks when customer last modified
  /// settings.
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade, map: "shopping_mall_customer_order_preferences_shopping_mall_7e6c98e3")

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_customer_id], map: "shopping_mall_customer_order_preferences_shopping_mall_bfb2bd75")
}

schemas.schema-07-payments.prisma:
/// Core payment records for customer orders. Stores order-level payment
/// information including customer, order reference, payment method, and
/// final payment status. This is separate from detailed payment processor
/// transactions to maintain clean separation of concerns between order-level
/// payment state and gateway-level transaction details.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_payments {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the order being paid for. {@link shopping_mall_orders.id}
  shopping_mall_order_id String @db.Uuid

  /// Customer making the payment. {@link shopping_mall_customers.id}
  shopping_mall_customer_id String @db.Uuid

  /// Payment method used for this transaction. {@link
  /// shopping_mall_payment_methods.id}
  shopping_mall_payment_method_id String? @db.Uuid

  /// Human-readable order number for reference (e.g., ORD-20250115-ABC123)
  order_number String

  /// Payment amount in platform currency (stored in cents to avoid floating
  /// point errors)
  amount Float @db.DoublePrecision

  /// ISO 4217 currency code (USD, EUR, INR, etc.)
  currency String

  /// Current payment status: pending_payment, payment_processing,
  /// payment_confirmed, payment_failed, payment_pending, refund_processing,
  /// refund_completed, refund_failed
  payment_status String

  /// Type of payment method: credit_card, debit_card, paypal, bank_transfer,
  /// digital_wallet
  payment_method_type String

  /// Last 4 digits of card (if card payment), masked for security
  card_last_four String?

  /// Name on the payment method
  cardholder_name String?

  /// Billing address provided at payment time (JSON formatted for address
  /// components)
  billing_address String?

  /// Authorization code from payment processor if transaction was approved
  authorization_code String?

  /// Unique transaction ID from payment processor
  transaction_id String?

  /// Standardized response code from payment processor (00 for success, etc.)
  response_code String?

  /// Human-readable response message from payment processor
  response_message String?

  /// Error code if transaction failed (insufficient funds, expired card, etc.)
  error_code String?

  /// Detailed error explanation if transaction declined or failed
  error_message String?

  /// Risk assessment score from payment processor (0-100, higher = more risky)
  fraud_score Float? @db.DoublePrecision

  /// 3D Secure authentication status: not_applicable, authenticated,
  /// attempted, not_enrolled
  three_d_secure_status String?

  /// Unique key for idempotent payment processing to prevent duplicate charges
  idempotency_key String?

  /// Customer IP address when payment was attempted
  ip_address String?

  /// Browser/device user agent information
  user_agent String?

  /// When the payment request was received
  request_timestamp DateTime @db.Timestamptz

  /// When payment authorization was received from processor
  authorization_timestamp DateTime? @db.Timestamptz

  /// Payment record creation timestamp
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for this payment record
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)
  paymentMethod shopping_mall_payment_methods? @relation(fields: [shopping_mall_payment_method_id], references: [id], onDelete: Cascade)

  shopping_mall_payment_transactions shopping_mall_payment_transactions[]
  shopping_mall_refunds shopping_mall_refunds[]

  @@unique([shopping_mall_order_id])
  @@index([shopping_mall_payment_method_id])

  @@unique([transaction_id])
  @@unique([idempotency_key])
  @@index([shopping_mall_customer_id, created_at])
  @@index([payment_status])
  @@index([created_at])
}

/// Detailed payment processor transaction records. Captures every
/// interaction with the payment gateway including authorization, capture,
/// decline, refund, reversal events. Maintains complete audit trail of
/// payment processor responses. Separate from shopping_mall_payments to
/// preserve immutable transaction history while allowing payment status
/// updates.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_payment_transactions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the parent payment record. {@link shopping_mall_payments.id}
  shopping_mall_payment_id String @db.Uuid

  /// Type of transaction: authorization, capture, decline, refund, reversal,
  /// adjustment, chargeback
  transaction_type String

  /// Status of this specific transaction: pending, successful, failed,
  /// cancelled
  transaction_status String

  /// Transaction amount (may differ from original payment if partial refund,
  /// etc.)
  amount Float @db.DoublePrecision

  /// Currency code for this transaction
  currency String

  /// Transaction ID from payment processor
  gateway_transaction_id String?

  /// Reference ID from payment processor (for linking related transactions)
  gateway_reference_id String?

  /// Authorization code if applicable
  authorization_code String?

  /// Response code from payment processor
  response_code String?

  /// Response message from payment processor
  response_message String?

  /// Error code if transaction failed
  error_code String?

  /// Error message if transaction failed
  error_message String?

  /// Address Verification System response (if card transaction)
  avs_response String?

  /// CVV verification response (if card transaction)
  cvv_response String?

  /// Full request JSON sent to payment processor (for audit trail, no
  /// sensitive data)
  request_payload String?

  /// Full response JSON received from payment processor (for audit trail)
  response_payload String?

  /// When request was sent to payment processor
  request_timestamp DateTime @db.Timestamptz

  /// When response was received from payment processor
  response_timestamp DateTime? @db.Timestamptz

  /// Record creation timestamp
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  payment shopping_mall_payments @relation(fields: [shopping_mall_payment_id], references: [id], onDelete: Cascade, map: "shopping_mall_payment_transactions_shopping_mall_payme_00e9c6a8")

  @@unique([gateway_transaction_id])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_payment_id, transaction_type], map: "shopping_mall_payment_transactions_shopping_mall_payme_8b97725a")
  @@index([transaction_status])
  @@index([created_at])
}

/// Refund request and processing records. Tracks lifecycle of refunds from
/// initiation through completion. Separate entity (not nullable fields on
/// payments) enables proper refund state management and audit trail. Refunds
/// can be partial, have multiple statuses, and require approval workflows.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_refunds {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the original payment being refunded. {@link
  /// shopping_mall_payments.id}
  shopping_mall_payment_id String @db.Uuid

  /// Reference to the order. {@link shopping_mall_orders.id}
  shopping_mall_order_id String @db.Uuid

  /// Unique refund identifier (REF-YYYYMMDD-XXXXXX format)
  refund_number String

  /// Reason for refund: customer_request, payment_failure,
  /// seller_cancellation, order_cancellation, return_accepted,
  /// dispute_resolution, chargeback, other
  refund_reason String

  /// Amount to be refunded (may be less than original payment for partial
  /// refunds)
  refund_amount Float @db.DoublePrecision

  /// Original payment amount (for reference)
  original_amount Float @db.DoublePrecision

  /// Current refund status: initiated, approved, processing, completed,
  /// failed, reversed, cancelled
  refund_status String

  /// How refund will be issued: original_payment_method, store_credit,
  /// bank_transfer, other
  refund_method String

  /// Amount deducted from refund (restocking fee, condition deduction, etc.)
  deduction_amount Float? @db.DoublePrecision

  /// Reason for deduction (e.g., item condition, restocking fee)
  deduction_reason String?

  /// Internal notes about this refund (admin comments, investigation notes,
  /// etc.)
  notes String?

  /// Who initiated the refund: customer, seller, admin, system
  initiated_by String

  /// Admin ID who approved the refund (if applicable)
  approved_by String?

  /// When refund was initiated
  initiation_timestamp DateTime @db.Timestamptz

  /// When refund was approved for processing
  approval_timestamp DateTime? @db.Timestamptz

  /// When refund processing was initiated with payment processor
  processing_timestamp DateTime? @db.Timestamptz

  /// When refund was completed/credited to customer
  completion_timestamp DateTime? @db.Timestamptz

  /// Expected date/time refund will appear in customer account
  expected_completion_date DateTime? @db.Timestamptz

  /// Refund ID from payment processor
  gateway_refund_id String?

  /// Record creation timestamp
  created_at DateTime @db.Timestamptz

  /// Last update timestamp
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  payment shopping_mall_payments @relation(fields: [shopping_mall_payment_id], references: [id], onDelete: Cascade)
  order shopping_mall_orders @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)

  @@unique([refund_number])
  @@unique([gateway_refund_id])
  @@index([shopping_mall_payment_id])
  @@index([shopping_mall_order_id])
  @@index([refund_status])
  @@index([initiation_timestamp])
}

/// Customer payment methods stored on file. Tokenized payment references for
/// reuse, avoiding storage of complete sensitive data. Each payment method
/// is linked to a customer and can be marked as primary or deleted. Supports
/// credit cards, digital wallets, and bank accounts.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_payment_methods {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Customer who owns this payment method. {@link shopping_mall_customers.id}
  shopping_mall_customer_id String @db.Uuid

  /// Type of payment method: credit_card, debit_card, paypal, bank_account,
  /// digital_wallet
  payment_method_type String

  /// Tokenized reference from payment processor (never stores actual
  /// card/account data)
  payment_token String

  /// Customer-friendly name for this payment method (e.g., "My VISA", "PayPal
  /// Account")
  display_name String?

  /// Last 4 digits of card (if card payment) for display
  card_last_four String?

  /// Card brand for card payments: visa, mastercard, amex, discover
  card_brand String?

  /// Expiration month (1-12) for card payments
  expiration_month Int? @db.Integer

  /// Expiration year (4-digit) for card payments
  expiration_year Int? @db.Integer

  /// Name on the card
  cardholder_name String?

  /// Bank name for bank account payments
  bank_name String?

  /// Last 4 digits of bank account
  account_last_four String?

  /// Whether this is the customer's default payment method
  is_primary Boolean

  /// Whether this payment method is active/available for use
  is_active Boolean

  /// When this payment method was added
  created_at DateTime @db.Timestamptz

  /// Last update timestamp
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp if payment method is no longer available
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  customer shopping_mall_customers @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)

  shopping_mall_payments shopping_mall_payments[]

  @@unique([payment_token])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, is_primary], map: "shopping_mall_payment_methods_shopping_mall_customer_i_8f8ca36c")
  // spellchecker: ignore-next-line
  @@index([shopping_mall_customer_id, is_active], map: "shopping_mall_payment_methods_shopping_mall_customer_i_0f178e28")
}

/// Reconciliation records comparing system payment records with payment
/// processor settlements. Ensures all transactions are accounted for and any
/// discrepancies are detected. Tracks daily or periodic reconciliation runs.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_transaction_reconciliation {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Date for which reconciliation was performed
  reconciliation_date DateTime @db.Timestamptz

  /// Type of reconciliation: daily, weekly, monthly, manual, processor_report
  reconciliation_type String

  /// Which payment processor this reconciliation is for
  processor_name String

  /// Number of transactions recorded in our system for this period
  system_transaction_count Int @db.Integer

  /// Number of transactions reported by payment processor
  processor_transaction_count Int @db.Integer

  /// Total transaction amount in our system
  system_total_amount Float @db.DoublePrecision

  /// Total transaction amount reported by processor
  processor_total_amount Float @db.DoublePrecision

  /// Status of reconciliation: matched, discrepancy_found,
  /// pending_investigation, resolved
  reconciliation_status String

  /// Description of any discrepancies found
  discrepancy_details String?

  /// JSON array of transaction IDs missing from system
  missing_transaction_ids String?

  /// JSON array of transaction IDs in system but not in processor report
  extra_transaction_ids String?

  /// Admin user ID who performed or approved the reconciliation
  reconciled_by String?

  /// When reconciliation was performed
  reconciliation_timestamp DateTime @db.Timestamptz

  /// Notes on how discrepancies were resolved
  resolution_notes String?

  /// Record creation timestamp
  created_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  @@unique([reconciliation_date, processor_name], map: "shopping_mall_transaction_reconciliation_reconciliatio_6ef316b8")
  // spellchecker: ignore-next-line
  @@index([reconciliation_status], map: "shopping_mall_transaction_reconciliation_reconciliatio_c4b956bc")
  // spellchecker: ignore-next-line
  @@index([reconciliation_date], map: "shopping_mall_transaction_reconciliation_reconciliatio_79b106b2")
}

/// Seller payment records tracking when payouts are issued to sellers.
/// Records amount, status, and settlement details. Separate from customer
/// refunds - this is seller compensation for successful sales.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_seller_payouts {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller receiving the payout. {@link shopping_mall_sellers.id}
  shopping_mall_seller_id String @db.Uuid

  /// Unique payout identifier (PAYOUT-YYYYMMDD-XXXXXX format)
  payout_number String

  /// Start date of the period covered by this payout
  payout_period_start DateTime @db.Timestamptz

  /// End date of the period covered by this payout
  payout_period_end DateTime @db.Timestamptz

  /// Gross sales amount before commissions and fees
  total_sales_amount Float @db.DoublePrecision

  /// Platform commission deducted from sales
  commission_amount Float @db.DoublePrecision

  /// Total refunds processed in this period
  refunds_amount Float @db.DoublePrecision

  /// Other fees deducted (payment processing, etc.)
  fees_amount Float? @db.DoublePrecision

  /// Final amount to be paid to seller (gross - commissions - refunds - fees)
  net_payout_amount Float @db.DoublePrecision

  /// Status of payout: pending, approved, processing, completed, failed,
  /// cancelled
  payout_status String

  /// How payout is issued: bank_transfer, wire, check, digital_wallet
  payout_method String

  /// Reference to seller's saved bank account for payout (if applicable)
  bank_account_id String? @db.Uuid

  /// Transaction ID or reference from payment processor
  transaction_reference String?

  /// When payout was initiated
  initiated_timestamp DateTime @db.Timestamptz

  /// When payout was completed/deposited
  completed_timestamp DateTime? @db.Timestamptz

  /// Expected date funds will appear in seller's account
  expected_delivery_date DateTime? @db.Timestamptz

  /// Reason for payout failure if applicable
  failure_reason String?

  /// Internal notes about this payout
  notes String?

  /// Record creation timestamp
  created_at DateTime @db.Timestamptz

  /// Last update timestamp
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade)

  @@unique([payout_number])
  // spellchecker: ignore-next-line
  @@index([shopping_mall_seller_id, payout_period_start], map: "shopping_mall_seller_payouts_shopping_mall_seller_id_p_d6c288ae")
  @@index([payout_status])
  @@index([initiated_timestamp])
}

/// Current account balance for each seller. Tracks the amount owed to seller
/// from completed sales, updated as orders are fulfilled and refunds
