model shopping_mall_seller_account_balances {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Seller whose balance this tracks. {@link shopping_mall_sellers.id}
  shopping_mall_seller_id String @db.Uuid

  /// Current available balance ready for payout
  current_balance Float @db.DoublePrecision

  /// Balance from orders not yet confirmed delivered
  pending_balance Float @db.DoublePrecision

  /// Balance held due to disputes or pending investigation
  reserved_balance Float @db.DoublePrecision

  /// Total cumulative earnings since seller joined platform
  lifetime_earnings Float @db.DoublePrecision

  /// Total cumulative payouts already processed
  lifetime_payouts Float @db.DoublePrecision

  /// Last time balance was updated
  last_balance_update DateTime @db.Timestamptz

  /// Record creation timestamp
  created_at DateTime @db.Timestamptz

  /// Last update timestamp
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  seller shopping_mall_sellers @relation(fields: [shopping_mall_seller_id], references: [id], onDelete: Cascade, map: "shopping_mall_seller_account_balances_shopping_mall_se_3f6c47f3")

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_seller_id], map: "shopping_mall_seller_account_balances_shopping_mall_se_7ba2e853")

  @@index([current_balance])
}

/// Commission rate configuration by product category. Defines what
/// percentage of each sale the platform retains as commission. Supports
/// variable rates to optimize for different categories. Historical records
/// track rate changes over time.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_commission_rates {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Product category this commission rate applies to. {@link
  /// shopping_mall_categories.id}
  shopping_mall_category_id String @db.Uuid

  /// Category name for reference (denormalized from category table)
  category_name String

  /// Commission percentage (0-100) that platform retains from each sale
  commission_percentage Float @db.DoublePrecision

  /// Minimum commission amount even if percentage would be less
  minimum_commission_amount Float? @db.DoublePrecision

  /// Maximum commission amount capped at this value
  maximum_commission_amount Float? @db.DoublePrecision

  /// Date when this commission rate becomes effective
  effective_date DateTime @db.Timestamptz

  /// Date when this commission rate expires (null if current)
  expiration_date DateTime? @db.Timestamptz

  /// Description of why this rate was set (e.g., promotional rate, category
  /// adjustment)
  description String?

  /// Admin ID who created this rate
  created_by String

  /// Record creation timestamp
  created_at DateTime @db.Timestamptz

  /// Last update timestamp
  updated_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  category shopping_mall_categories @relation(fields: [shopping_mall_category_id], references: [id], onDelete: Cascade)

  @@unique([shopping_mall_category_id])

  // spellchecker: ignore-next-line
  @@index([effective_date, expiration_date], map: "shopping_mall_commission_rates_effective_date_expirati_f36e0891")
}

/// General ledger tracking all financial movements: customer payments,
/// seller payouts, refunds, commissions, adjustments. Immutable audit trail
/// of financial transactions for accounting and compliance. Supports
/// platform financial reporting and reconciliation.
///
/// @namespace Payments
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_financial_ledger {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Related order if applicable. {@link shopping_mall_orders.id}
  shopping_mall_order_id String? @db.Uuid

  /// Date of the financial transaction
  ledger_date DateTime @db.Timestamptz

  /// Type of financial transaction: sale, refund, payout, commission,
  /// adjustment, chargeback, fee
  transaction_type String

  /// Account being debited (reduced) - typically customer or seller account ID
  debit_account String?

  /// Account being credited (increased) - typically platform or seller account
  credit_account String?

  /// Transaction amount
  amount Float @db.DoublePrecision

  /// Currency code
