  shopping_mall_dispute_appeals shopping_mall_dispute_appeals[]
  shopping_mall_dispute_audit_trail shopping_mall_dispute_audit_trail[]

  @@unique([dispute_id])
  @@index([shopping_mall_customer_id, created_at])
  @@index([shopping_mall_seller_id, created_at])
  @@index([status, created_at])
  @@index([assigned_admin_id])
  @@index([shopping_mall_order_id])
  @@index([priority, status])
  @@index([reason_description(ops: raw("gin_trgm_ops"))], type: Gin)
