  // spellchecker: ignore-next-line
  category shopping_mall_categories @relation(fields: [shopping_mall_category_id], references: [id], onDelete: Cascade, map: "shopping_mall_product_categories_mapping_shopping_mall_36f3d657")

  // spellchecker: ignore-next-line
  @@unique([shopping_mall_product_id, shopping_mall_category_id], map: "shopping_mall_product_categories_mapping_shopping_mall_0203e069")
