  /// Timestamp when price change was applied
  changed_at DateTime @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  product shopping_mall_products          @relation(fields: [shopping_mall_product_id], references: [id], onDelete: Cascade, map: "shopping_mall_product_pricing_history_shopping_mall_pr_95a9560f")
  // spellchecker: ignore-next-line
  variant shopping_mall_product_variants? @relation(fields: [shopping_mall_product_variant_id], references: [id], onDelete: Cascade, map: "shopping_mall_product_pricing_history_shopping_mall_pr_d8aa3501")

  // spellchecker: ignore-next-line
