/// Customer-initiated return requests for delivered orders. Stores the
/// initial return request with customer reason, optional evidence (photos),
/// and desired resolution. This is the first stage of the return lifecycle
/// where customers express intent to return a product.
///
/// @namespace Returns
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model shopping_mall_return_requests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Reference to the order being returned. {@link shopping_mall_orders.id}
  shopping_mall_order_id String @db.Uuid

  /// Customer who initiated the return request. {@link
  /// shopping_mall_customers.id}
  shopping_mall_customer_id String @db.Uuid

  /// Specific line item being returned (if partial return). {@link
  /// shopping_mall_order_line_items.id}
  shopping_mall_order_line_item_id String? @db.Uuid

  /// Human-readable return request number in format RR-YYYYMMDD-XXXXXX for
  /// customer reference
  return_request_number String

  /// Customer-selected reason for return: Item not as described, Item arrived
  /// defective, Wrong item received, Item arrived damaged, Changed mind, Not
  /// needed, Other reason
  return_reason String

  /// Customer's detailed explanation of return reason (up to 500 characters)
  additional_details String?

  /// Customer's desired outcome: Full refund, Replacement, Store credit,
  /// Partial refund
  requested_resolution String?

  /// Number of units customer wants to return (for multi-unit orders)
  quantity_to_return Int @db.Integer

  /// JSON array of uploaded evidence image URLs (max 3 images) for
  /// damaged/defective items
  evidence_urls String?

  /// Return request status: pending, authorized, rejected, dispute_opened,
  /// withdrawn. Controls workflow progression.
  status String

  /// Timestamp when return request was initiated by customer
  created_at DateTime @db.Timestamptz

  /// Last update timestamp for return request
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp if return request is withdrawn
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  order    shopping_mall_orders            @relation(fields: [shopping_mall_order_id], references: [id], onDelete: Cascade)
  customer shopping_mall_customers         @relation(fields: [shopping_mall_customer_id], references: [id], onDelete: Cascade)
  // spellchecker: ignore-next-line
  lineItem shopping_mall_order_line_items? @relation(fields: [shopping_mall_order_line_item_id], references: [id], onDelete: Cascade, map: "shopping_mall_return_requests_shopping_mall_order_line_5fb307a6")

  shopping_mall_return_authorizations shopping_mall_return_authorizations?
